function uni02_plots(out,b,f,slow,fast,s,trials)
dest=fullfile(out,'figures'); if ~isfolder(dest), mkdir(dest); end; catalog=struct('file',{},'field',{},'meaning',{});
set(groot,'defaultFigureVisible','off','defaultAxesFontSize',20,'defaultTextFontSize',20,'defaultAxesColorOrder',[0 .46 .73;.0 .66 .72;.8 .45 .1;.2 .25 .32]);
map(b.mask,'01 Resource map','b.mask','Data=1; DM-RS=2','Symbol index','Subcarrier index');
fig; plot(real(b.dmrs(1:72)),'o-'); hold on; plot(imag(b.dmrs(1:72)),'s-'); legend('Real','Imaginary'); labels('Generated reference sequence','Reference element index','Normalized amplitude'); finish('02 DMRS sequence','b.dmrs','Known complex symbols used by the estimator');
fig; scatter(real(b.dmrs),imag(b.dmrs),60,'filled'); axis equal; xlim([-1 1]); ylim([-1 1]); labels('Reference symbol alphabet','In phase','Quadrature'); finish('03 DMRS constellation','b.dmrs','Constant modulus QPSK reference alphabet');
map(angle(b.tx).*(abs(b.tx)>0),'04 Transmitted grid','b.tx','Phase (rad) of each occupied element','Symbol index','Subcarrier index');
map(abs(b.H),'05 True channel magnitude','b.H','Frequency selective fade magnitude','Symbol index','Subcarrier index');
map(angle(b.H),'06 True channel phase','b.H','Phase in radians for the baseline channel','Symbol index','Subcarrier index');
map(abs(b.rx),'07 Received grid','b.rx','Fades and noise change the received amplitude','Symbol index','Subcarrier index');
fig; scatter(real(b.rx(b.dataIndices)),imag(b.rx(b.dataIndices)),6,'filled'); axis equal; labels('Data before equalization','In phase','Quadrature'); finish('08 Received constellation','b.rx(dataIndices)','Raw data symbols rotate and scale with subcarrier response');
ls=b.rx(b.dmrsIndices)./b.dmrs; fig; plot(abs(ls(1:144)),'.'); hold on; plot(abs(b.H(b.dmrsIndices(1:144))),'LineWidth',2); legend('Pilot division','Truth'); labels('Channel samples at pilot elements','Pilot element index','Magnitude'); finish('09 Pilot channel samples','b.rx ./ b.dmrs','Least squares samples compared with evaluation truth');
map(abs(b.Hhat),'10 Estimated channel magnitude','b.Hhat','Practical interpolated channel estimate','Symbol index','Subcarrier index');
map(abs(b.Hhat-b.H).^2,'11 Channel estimation error','b.Hhat-b.H','Squared complex estimation error','Symbol index','Subcarrier index');
fig; plot(abs(b.H(:,7)),'LineWidth',2); hold on; plot(abs(b.Hhat(:,7)),'--','LineWidth',2); legend('Truth','Practical'); labels('Channel interpolation at symbol 6','Subcarrier index','Magnitude'); finish('12 Frequency interpolation','b.H(:,7), b.Hhat(:,7)','Estimated response through deep frequency fades');
fig; scatter(real(b.eq),imag(b.eq),6,'filled'); axis equal; labels('Data after practical equalization','In phase','Quadrature'); finish('13 Equalized constellation','b.eq','MMSE equalization restores four decision regions');
fig; scatter(real(b.perfect),imag(b.perfect),6,'filled'); axis equal; labels('Equalization using true channel','In phase','Quadrature'); finish('14 Oracle constellation','b.perfect','Evaluation reference isolates channel estimation loss');
fig; histogram(b.llr(b.bits==0),40); hold on; histogram(b.llr(b.bits==1),40); legend('Sent zero','Sent one'); labels('Descrambled soft bit evidence','Log likelihood ratio','Count'); finish('15 Soft bit distributions','b.llr, b.bits','Likelihood sign separates the two bit hypotheses');
fig; stem(find(b.bits~=b.bhat),ones(sum(b.bits~=b.bhat),1)); labels('Baseline bit errors','Payload bit index','Error indicator'); ylim([0 1.2]); xlim([0 numel(b.bits)]); if ~any(b.bits~=b.bhat), text(0.5,0.5,sprintf('No bit errors in %d payload bits',numel(b.bits)),'Units','normalized','HorizontalAlignment','center'); end; finish('16 Bit error locations','b.bits ~= b.bhat','Errors are traced to their original bit positions');
fig; scatter(real(f.eq),imag(f.eq),6,'filled'); axis equal; labels('Wrong reference identity','In phase','Quadrature'); finish('17 Identity failure constellation','f.eq','Wrong DM-RS sequence destroys the estimate even at 25 dB');
fig; plot(0:13,unwrap(angle(slow.Hhat(1,:).*conj(slow.H(1,:)))),'--','LineWidth',2); hold on; plot(0:13,unwrap(angle(fast.Hhat(1,:).*conj(fast.H(1,:)))),':','LineWidth',2); yline(0,'k-'); legend('One pilot symbol','Three pilot symbols','Zero error','Location','southwest'); labels('Phase estimation error at 1000 Hz','Symbol index','Estimate minus true phase (rad)'); finish('18 Phase tracking','slow.H, slow.Hhat, fast.H, fast.Hhat','Each estimate is compared with its own true channel phase');
fig; for ap=[0 2], q=s(s.DopplerHz==0&s.Additional==ap,:); semilogy(q.SNRdB,max(q.BER,1e-6),'-o','LineWidth',2); hold on; end; legend('One pilot symbol','Three pilot symbols'); labels('Bit errors in a static channel','SNR per active RE (dB)','Mean uncoded BER'); finish('19 BER scan','summary.BER','Values below plotting floor 1e-6 require the CSV');
fig; for ap=[0 2], q=s(s.SNRdB==25&s.Additional==ap,:); plot(q.DopplerHz,q.EVM*100,'-o','LineWidth',2); hold on; end; legend('One pilot symbol','Three pilot symbols'); labels('Phase variation and equalization error','Common phase rate (Hz)','RMS EVM (%)'); finish('20 Phase rate scan','summary.EVM','EVM includes residual bias and noise after equalization');
fig; for ap=[0 2], q=s(s.DopplerHz==1000&s.Additional==ap,:); errorbar(q.SNRdB,q.Failures./q.Trials,q.Failures./q.Trials-q.WilsonLow,q.WilsonHigh-q.Failures./q.Trials,'-o','LineWidth',2); hold on; end; legend('One pilot symbol','Three pilot symbols'); labels('Demodulation block failure at 1000 Hz','SNR per active RE (dB)','Probability with 95% interval'); ylim([0 1.05]); finish('21 Block failure intervals','summary.Failures, WilsonLow, WilsonHigh','Failure means uncoded BER above 0.05; 30 independent trials per point');
fig; q=s(s.Additional==2&s.DopplerHz==0,:); semilogy(q.SNRdB,q.NMSE,'-o','LineWidth',2); labels('Channel estimate improves with SNR','SNR per active RE (dB)','Normalized mean squared error'); finish('22 Estimation NMSE','summary.NMSE','Complex grid error normalized by true channel energy');
pm=b.mask; pm(b.ptrsIndices)=3; map(pm,'23 Optional PTRS map','b.ptrsIndices','Candidate mapping only: data=1, DM-RS=2, PT-RS=3','Symbol index','Subcarrier index');
fig; histogram(trials.NoiseEstimate(trials.SNRdB==25 & trials.DopplerHz==0 & trials.Additional==2),10); hold on; xline(b.noiseVariance,'--','LineWidth',2); labels('Noise estimate variability at 25 dB','Estimated variance','Trial count'); finish('24 Noise estimation','trials.NoiseEstimate','Dashed line is injected normalized RE noise variance');
fid=fopen(fullfile(dest,'catalog.json'),'w'); fprintf(fid,'%s',jsonencode(catalog,PrettyPrint=true)); fclose(fid);
function fig, pubfig.new('wide'); end
function labels(tt,xx,yy), title(tt); xlabel(xx); ylabel(yy); grid on; end
function map(z,n,field,meaning,xx,yy), fig; imagesc(0:13,0:287,z); axis xy; colorbar; if max(z(:))-min(z(:))<1e-6, clim([0 max(1,max(z(:)))]); end; labels(n(4:end),xx,yy); finish(n,field,meaning); end
function finish(n,field,meaning), file=['Uni-02 - ' n ' v2.png']; pubfig.export(gcf,fullfile(dest,file)); close(gcf); catalog(end+1)=struct('file',file,'field',field,'meaning',meaning); end
end
